-- Generated by hyprmoncfg

-- hyprmoncfg owns monitor configuration, so Omarchy's display panel settings stand down.
omarchy_monitor_panel_settings = false

hl.monitor({
  output = "desc:Apple Computer Inc Color LCD",
  mode = "2880x1800@60.00",
  position = "0x0",
  scale = 1.25,
  vrr = 0,
  cm = "auto",
  sdr_min_luminance = 0.2,
  sdr_max_luminance = 80,
})

hl.monitor({
  output = "desc:Dell Inc. DELL P2416D 07C5368H2DPL",
  mode = "2560x1440@59.95",
  position = "2304x0",
  scale = 1,
  vrr = 0,
  cm = "auto",
  sdr_min_luminance = 0.2,
  sdr_max_luminance = 80,
})

-- hyprmoncfg owns the global workspace plan. Omarchy's monitor-local
-- handlers must stand down alongside the rules below. Plain Hyprland is unchanged.
if type(o) == "table" and type(o.workspaces) == "table" and type(o.workspaces.reconcile) == "function" and type(o.rebind) == "function" then
  -- Omarchy's event callbacks call this through the module table, including on
  -- startup, reload and hotplug. Disable its reassignment before those run.
  o.workspaces.enabled = false
  o.workspaces.reconcile = function() end

  -- The plan's persistent workspaces. Hyprland keeps one on the monitor its
  -- rule names and moves it back after a move (#123).
  local persistent = { ["1"] = true, ["4"] = true }

  local function action(expression, fn)
    o.bind_expressions[fn] = expression
    return fn
  end

  function o.workspaces.focus(workspace)
    return action("o.workspaces.focus(" .. string.format("%q", tostring(workspace)) .. ")", function()
      hl.dispatch(hl.dsp.focus({ workspace = tostring(workspace) }))
    end)
  end

  function o.workspaces.move_window(workspace, follow)
    return action("o.workspaces.move_window(" .. workspace .. ", " .. tostring(follow ~= false) .. ")", function()
      hl.dispatch(hl.dsp.window.move({ workspace = tostring(workspace), follow = follow ~= false }))
    end)
  end

  function o.workspaces.move_to_monitor(direction)
    return action("o.workspaces.move_to_monitor(" .. string.format("%q", direction) .. ")", function()
      -- workspace.move takes a monitor, not a direction. Resolve it first;
      -- with no monitor that way, Hyprland would report an error on screen.
      local target = hl.get_monitor(direction)
      if not target then
        return
      end
      -- Pin a persistent planned workspace to its new monitor first, so it
      -- stays there. The rule lives until the next reload, which restores
      -- the plan; the saved profile is unchanged.
      local workspace = hl.get_active_workspace()
      if workspace and persistent[tostring(workspace.id)] then
        hl.workspace_rule({ workspace = tostring(workspace.id), monitor = target.name, persistent = true, default = false })
      end
      hl.dispatch(hl.dsp.workspace.move({ monitor = target.name }))
    end)
  end

  -- Replace Omarchy's monitor-local number bindings with global destinations.
  for workspace = 1, 10 do
    local key = "code:" .. tostring(workspace + 9)
    o.rebind("SUPER + " .. key, "Switch to workspace " .. workspace, o.workspaces.focus(workspace))
    o.rebind("SUPER + SHIFT + " .. key, "Move window to workspace " .. workspace, o.workspaces.move_window(workspace))
    o.rebind("SUPER + SHIFT + ALT + " .. key, "Move window silently to workspace " .. workspace, o.workspaces.move_window(workspace, false))
  end

  o.rebind("SUPER + TAB", "Next workspace", o.workspaces.focus("e+1"))
  o.rebind("SUPER + SHIFT + TAB", "Previous workspace", o.workspaces.focus("e-1"))
  o.rebind("SUPER + CTRL + TAB", "Former workspace", o.workspaces.focus("previous"))
  o.rebind("SUPER + mouse_down", "Scroll active workspace forward", o.workspaces.focus("e+1"))
  o.rebind("SUPER + mouse_up", "Scroll active workspace backward", o.workspaces.focus("e-1"))

  for key, direction in pairs({ LEFT = "l", RIGHT = "r", UP = "u", DOWN = "d" }) do
    o.rebind("SUPER + SHIFT + ALT + " .. key, "Move workspace to " .. key:lower() .. " monitor", o.workspaces.move_to_monitor(direction))
  end
end

hl.workspace_rule({ workspace = "1", monitor = "desc:Apple Computer Inc Color LCD", default = true, persistent = true })
hl.workspace_rule({ workspace = "2", monitor = "desc:Apple Computer Inc Color LCD" })
hl.workspace_rule({ workspace = "3", monitor = "desc:Apple Computer Inc Color LCD" })
hl.workspace_rule({ workspace = "4", monitor = "desc:Dell Inc. DELL P2416D 07C5368H2DPL", default = true, persistent = true })
hl.workspace_rule({ workspace = "5", monitor = "desc:Dell Inc. DELL P2416D 07C5368H2DPL" })
hl.workspace_rule({ workspace = "6", monitor = "desc:Dell Inc. DELL P2416D 07C5368H2DPL" })

-- Omarchy leaves GDK_SCALE to this file.
if type(o) == "table" then
  hl.env("GDK_SCALE", "1")
  hl.exec_cmd("dbus-update-activation-environment --systemd GDK_SCALE=1")
end

-- Omarchy's Mirror Display toggle takes effect over the profile while it is on.
do
  local state = os.getenv("XDG_STATE_HOME") or (os.getenv("HOME") .. "/.local/state")
  local path = state .. "/omarchy/toggles/hypr/internal-monitor-mirror.lua"
  local file = io.open(path, "r")
  if type(o) == "table" and file then
    file:close()
    dofile(path)
  elseif file then
    file:close()
  end
end

hl.config({ input = { touchdevice = { transform = 0 }, tablet = { transform = 0 } } })
